-- course offerings catalog

DROP TABLE IF EXISTS `course_offerings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_offerings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `course_id` int(11) NOT NULL,
  `programme_group` varchar(191) NOT NULL,
  `batch_label` varchar(191) NOT NULL,
  `year_of_study` int(11) NOT NULL,
  `semester` int(11) NOT NULL,
  `academic_session_start` datetime(3) NOT NULL,
  `academic_session_end` datetime(3) NOT NULL,
  `lecturer_in_charge_staff_id` int(11) DEFAULT NULL,
  `lecturer_in_charge_label` varchar(191) DEFAULT NULL,
  `teaching_type` varchar(191) NOT NULL,
  `merge_group_key` varchar(191) DEFAULT NULL,
  `source_document` varchar(191) NOT NULL,
  `source_review_status` varchar(191) NOT NULL DEFAULT 'APPROVED',
  `notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `course_offerings_course_id_fkey` (`course_id`),
  KEY `course_offerings_lecturer_in_charge_staff_id_fkey` (`lecturer_in_charge_staff_id`),
  CONSTRAINT `course_offerings_course_id_fkey` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `course_offerings_lecturer_in_charge_staff_id_fkey` FOREIGN KEY (`lecturer_in_charge_staff_id`) REFERENCES `staff_directory` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
