-- notification emails sent by system

DROP TABLE IF EXISTS `email_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `email_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `recipient_user_id` int(11) DEFAULT NULL,
  `recipient_email` varchar(191) NOT NULL,
  `recipient_name` varchar(191) NOT NULL,
  `subject` varchar(191) NOT NULL,
  `template_key` varchar(191) NOT NULL,
  `content_html` text NOT NULL,
  `content_text` text NOT NULL,
  `exam_schedule_id` int(11) DEFAULT NULL,
  `sent_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `status` varchar(191) NOT NULL DEFAULT 'SENT',
  PRIMARY KEY (`id`),
  KEY `email_logs_recipient_email_idx` (`recipient_email`),
  KEY `email_logs_exam_schedule_id_idx` (`exam_schedule_id`),
  KEY `email_logs_recipient_user_id_fkey` (`recipient_user_id`),
  CONSTRAINT `email_logs_exam_schedule_id_fkey` FOREIGN KEY (`exam_schedule_id`) REFERENCES `exam_schedules` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `email_logs_recipient_user_id_fkey` FOREIGN KEY (`recipient_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

