LOCK TABLES `email_logs` WRITE;
/*!40000 ALTER TABLE `email_logs` DISABLE KEYS */;
INSERT INTO `email_logs` VALUES (1,2,'charith@rusl.ac.lk','Dr. Charith Jayasundara (Updated)','[Approved & Locked] Final Results Released: COM1302','FINAL_RESULTS_APPROVED_LOCKED','\n      <div style=\"font-family: Arial, sans-serif; padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px;\">\n        <h3 style=\"color: #065f46;\">Results Approved & Workflow Permanently Locked</h3>\n        <p>Dear Dr. Charith Jayasundara (Updated),</p>\n        <p>Final approval has been granted by <strong>Dr. K. A. S. H. Kulathilake</strong> (HOD) for <strong>COM1302 (Database Management System)</strong>. Workflow is now locked.</p>\n      </div>\n    ','Dear Dr. Charith Jayasundara (Updated),\n\nThe Final Marksheet for COM1302 (Database Management System) has received FINAL APPROVAL from the Head of Department (Dr. K. A. S. H. Kulathilake).\n\nPursuant to RUSL Examination Regulations, the examination results workflow has been permanently locked. No further modifications or document replacements are permitted.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 20:33:19.697','DELIVERED'),(2,2,'charith@rusl.ac.lk','Dr. Charith Jayasundara (Updated)','[Action Required] Exam Concluded: Collect Paper Packets for ICT1306 (Handover OTP: 743163)','EXAM_ENDED_COLLECTION_CALL','\n      <div style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #1e293b; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden;\">\n        <div style=\"background: linear-gradient(135deg, #881337, #4c0519); color: white; padding: 24px; text-align: center;\">\n          <h2 style=\"margin: 0; font-size: 20px;\">Rajarata University of Sri Lanka</h2>\n          <p style=\"margin: 4px 0 0; font-size: 13px; color: #fecdd3;\">Examinations Branch • Script Handover Call</p>\n        </div>\n        <div style=\"padding: 24px;\">\n          <p style=\"font-size: 15px; margin-top: 0;\">Dear <strong>Dr. Charith Jayasundara (Updated)</strong>,<br>\n          <span style=\"color: #64748b; font-size: 13px;\">Senior Lecturer Grade I</span></p>\n\n          <p>The examination for <strong>ICT1306 (Object Oriented Programming)</strong> has concluded. The physical answer script packets are ready for collection at the AR Office.</p>\n\n          <div style=\"background: #f8fafc; border: 2px dashed #94a3b8; border-radius: 10px; padding: 18px; text-align: center; margin: 20px 0;\">\n            <span style=\"font-size: 12px; font-weight: bold; color: #64748b; text-transform: uppercase; letter-spacing: 1px;\">Single-Use Collection Handover OTP</span>\n            <div style=\"font-size: 32px; font-family: monospace; font-weight: bold; color: #881337; letter-spacing: 6px; margin: 8px 0;\">\n              743163\n            </div>\n            <span style=\"font-size: 12px; color: #475569;\">Tell this code to the AR Office officer upon in-person collection.</span>\n          </div>\n\n          <p style=\"font-size: 13px; color: #475569;\"><strong>Regulatory Note:</strong> Pursuant to RUSL Examination Regulations Section 6.3, successful verification of this OTP officially stamps physical custody handover and calculates your 3-calendar-month marking due date.</p>\n        </div>\n        <div style=\"background: #f1f5f9; padding: 14px; text-align: center; font-size: 11px; color: #64748b; border-top: 1px solid #e2e8f0;\">\n          Department of Computing • Faculty of Applied Sciences • Mihintale\n        </div>\n      </div>\n    ','Dear Dr. Charith Jayasundara (Updated),\nSenior Lecturer Grade I,\n\nThe examination for ICT1306 (Object Oriented Programming) conducted on 8/15/2026 has concluded. The physical examination paper packets (approx. 75 scripts) have been deposited and secured at the Examinations Branch (AR Office).\n\nPlease proceed to the AR Office to collect your paper packets.\n\n==================================================\nYOUR PHYSICAL SCRIPT COLLECTION OTP:\n>>> 743163 <<<\n==================================================\n\nINSTRUCTIONS FOR HANDOVER:\n1. Visit the Examinations Branch counter in person.\n2. Tell this single-use 6-digit OTP code to the Senior Assistant Registrar (Examinations).\n3. The AR Office will verify the code in the system to confirm physical packet handover.\n4. Upon verification, your 3-calendar-month first marking deadline will officially commence.\n\nExaminations Branch & Department of Computing\nFaculty of Applied Sciences, Rajarata University of Sri Lanka',NULL,'2026-10-17 20:33:20.098','DELIVERED'),(3,5,'gunathilake@pdn.ac.lk','Prof. Jagath K. Gunathilake','[Scripts Dispatched] Courier Reference for ICT1306 Second Marking','COURIER_DISPATCHED_TO_SECOND_EXAMINER','\n      <div style=\"font-family: Arial, sans-serif; padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px;\">\n        <h3 style=\"color: #6b21a8;\">Scripts Dispatched via Courier</h3>\n        <p>Dear Prof. Jagath K. Gunathilake,</p>\n        <p>Answer scripts for <strong>ICT1306 (Object Oriented Programming)</strong> have been dispatched by the AR Office.</p>\n        <p><strong>Tracking Ref:</strong> SPEEDPOST-99921<br>\n        <strong>1-Month Due Date:</strong> 11/18/2026</p>\n        <p>Please acknowledge receipt once you receive the physical parcel.</p>\n      </div>\n    ','Dear Prof. Jagath K. Gunathilake,\n\nAnswer scripts for ICT1306 (Object Oriented Programming) have been dispatched to you via courier by the AR Office (Examinations Branch).\n\nCourier Tracking Reference: SPEEDPOST-99921\nSecond Marking Due Date: 11/18/2026 (1 Calendar Month)\n\nPlease sign in to acknowledge receipt upon receiving the physical package.\n\nExaminations Branch,\nRajarata University of Sri Lanka',NULL,'2026-10-17 20:33:20.364','DELIVERED'),(4,2,'charith@rusl.ac.lk','Dr. Charith Jayasundara (Updated)','Second Marking Completed: Prepare Final Marksheet for ICT1306','SECOND_MARKING_COMPLETED_PREPARE_MARKSHEET','\n      <div style=\"font-family: Arial, sans-serif; padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px;\">\n        <h3 style=\"color: #0369a1;\">Second Marking Completed</h3>\n        <p>Dear Dr. Charith Jayasundara (Updated),</p>\n        <p>Second marking for <strong>ICT1306 (Object Oriented Programming)</strong> is complete. You may now download the second marking report and submit the final marksheet for review.</p>\n      </div>\n    ','Dear Dr. Charith Jayasundara (Updated),\n\nSecond marking for ICT1306 (Object Oriented Programming) is now complete. The Second Marker Report PDF has been uploaded and scripts have been safely returned to the AR Office.\n\nYou can now download the Second Marker Report from the portal, compile your Continuous Assessment (CA) marks, and upload/submit the Final Marksheet for HOD approval.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 20:33:20.505','DELIVERED'),(5,1,'hod@rusl.ac.lk','Dr. K. A. S. H. Kulathilake','[HOD Review Required] Final Marksheet Submitted: ICT1306 (Dr. Charith Jayasundara (Updated))','FINAL_MARKSHEET_SUBMITTED_FOR_HOD_APPROVAL','\n      <div style=\"font-family: Arial, sans-serif; padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px;\">\n        <h3 style=\"color: #881337;\">Final Marksheet Submitted for Review</h3>\n        <p>Dear Dr. K. A. S. H. Kulathilake (HOD),</p>\n        <p><strong>Dr. Charith Jayasundara (Updated)</strong> has submitted the Final Marksheet for <strong>ICT1306 (Object Oriented Programming)</strong>. Please review and grant final approval.</p>\n      </div>\n    ','Dear Dr. K. A. S. H. Kulathilake,\nHead of Department,\n\nThe Final Marksheet for ICT1306 (Object Oriented Programming) has been compiled and submitted by the First Examiner (Dr. Charith Jayasundara (Updated)).\n\nAll prerequisite checkpoints (First Report, Scripts Returned, Second Report, AR Received) have been completed.\n\nPlease sign in to the HOD Dashboard to review the marksheet and either grant Final Approval (which permanently locks the workflow) or request revisions.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 20:33:20.627','DELIVERED'),(6,1,'hod@rusl.ac.lk','Dr. K. A. S. H. Kulathilake','[HOD Review Required] Final Marksheet Submitted: ICT1306 (Dr. Charith Jayasundara (Updated))','FINAL_MARKSHEET_SUBMITTED_FOR_HOD_APPROVAL','\n      <div style=\"font-family: Arial, sans-serif; padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px;\">\n        <h3 style=\"color: #881337;\">Final Marksheet Submitted for Review</h3>\n        <p>Dear Dr. K. A. S. H. Kulathilake (HOD),</p>\n        <p><strong>Dr. Charith Jayasundara (Updated)</strong> has submitted the Final Marksheet for <strong>ICT1306 (Object Oriented Programming)</strong>. Please review and grant final approval.</p>\n      </div>\n    ','Dear Dr. K. A. S. H. Kulathilake,\nHead of Department,\n\nThe Final Marksheet for ICT1306 (Object Oriented Programming) has been compiled and submitted by the First Examiner (Dr. Charith Jayasundara (Updated)).\n\nAll prerequisite checkpoints (First Report, Scripts Returned, Second Report, AR Received) have been completed.\n\nPlease sign in to the HOD Dashboard to review the marksheet and either grant Final Approval (which permanently locks the workflow) or request revisions.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 20:33:20.804','DELIVERED'),(7,2,'charith@rusl.ac.lk','Dr. Charith Jayasundara (Updated)','[Approved & Locked] Final Results Released: ICT1306','FINAL_RESULTS_APPROVED_LOCKED','\n      <div style=\"font-family: Arial, sans-serif; padding: 20px; border: 1px solid #e2e8f0; border-radius: 10px;\">\n        <h3 style=\"color: #065f46;\">Results Approved & Workflow Permanently Locked</h3>\n        <p>Dear Dr. Charith Jayasundara (Updated),</p>\n        <p>Final approval has been granted by <strong>Dr. K. A. S. H. Kulathilake</strong> (HOD) for <strong>ICT1306 (Object Oriented Programming)</strong>. W