INSERT INTO `notifications` VALUES (46,1,NULL,'SYSTEM_TEST_EMAIL','[Test Email] RUSL Examination Results Monitoring System','This is a test notification confirming that automated emails via Gmail are functioning correctly on the Examination Results Monitoring System.\n\nSent at: 2026-10-17T21:18:49.701Z',NULL,'2026-10-17 21:18:54.258'),(47,2,18,'FINAL_APPROVAL','Final Approval Granted','Your final marksheet submission has received final approval from the HOD and the workflow is locked.',NULL,'2026-10-17 21:41:14.153'),(48,2,22,'SCHEDULE_ASSIGNED','Exam Schedule Assigned','You have been assigned as First Examiner for ICT1306.',NULL,'2026-10-17 21:41:19.226'),(49,5,22,'SCHEDULE_ASSIGNED','Second Examiner Assignment Confirmed','You have been assigned as Second Examiner for ICT1306.',NULL,'2026-10-17 21:41:19.231'),(50,2,18,'FINAL_RESULTS_APPROVED_LOCKED','[Approved & Locked] Final Results Released: COM1302','Dear Dr. Charith Jayasundara (Updated),\n\nThe Final Marksheet for COM1302 (Database Management System) has received FINAL APPROVAL from the Head of Department (Dr. K. A. S. H. Kulathilake).\n\nPursuant to RUSL Examination Regulations, the examination results workflow has been permanently locked. No further modifications or document replacements are permitted.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 21:41:19.758'),(51,2,22,'EXAM_ENDED_COLLECTION_CALL','[Action Required] Exam Concluded: Collect Paper Packets for ICT1306 (Handover OTP: 915856)','Dear Dr. Charith Jayasundara (Updated),\nSenior Lecturer Grade I,\n\nThe examination for ICT1306 (Object Oriented Programming) conducted on 8/15/2026 has concluded. The physical examination paper packets (approx. 75 scripts) have been deposited and secured at the Examinations Branch (AR Office).\n\nPlease proceed to the AR Office to collect your paper packets.\n\n==================================================\nYOUR PHYSICAL SCRIPT COLLECTION OTP:\n>>> 915856 <<<\n==================================================\n\nINSTRUCTIONS FOR HANDOVER:\n1. Visit the Examinations Branch counter in person.\n2. Tell this single-use 6-digit OTP code to the Senior Assistant Registrar (Examinations).\n3. The AR Office will verify the code in the system to confirm physical packet handover.\n4. Upon verification, your 3-calendar-month first marking deadline will officially commence.\n\nExaminations Branch & Department of Computing\nFaculty of Applied Sciences, Rajarata University of Sri Lanka',NULL,'2026-10-17 21:41:23.949'),(52,5,22,'COURIER_DISPATCHED','Scripts Couriered','Scripts have been dispatched to you for second marking (Ref: SPEEDPOST-99921). Please acknowledge receipt once received.',NULL,'2026-10-17 21:41:24.114'),(53,2,18,'FINAL_APPROVAL','Final Approval Granted','Your final marksheet submission has received final approval from the HOD and the workflow is locked.',NULL,'2026-10-17 21:41:57.895'),(54,2,18,'FINAL_RESULTS_APPROVED_LOCKED','[Approved & Locked] Final Results Released: COM1302','Dear Dr. Charith Jayasundara (Updated),\n\nThe Final Marksheet for COM1302 (Database Management System) has received FINAL APPROVAL from the Head of Department (Dr. K. A. S. H. Kulathilake).\n\nPursuant to RUSL Examination Regulations, the examination results workflow has been permanently locked. No further modifications or document replacements are permitted.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 21:42:02.312'),(55,2,23,'SCHEDULE_ASSIGNED','Exam Schedule Assigned','You have been assigned as First Examiner for ICT1306.',NULL,'2026-10-17 21:42:02.456'),(56,5,23,'SCHEDULE_ASSIGNED','Second Examiner Assignment Confirmed','You have been assigned as Second Examiner for ICT1306.',NULL,'2026-10-17 21:42:02.462'),(57,2,23,'EXAM_ENDED_COLLECTION_CALL','[Action Required] Exam Concluded: Collect Paper Packets for ICT1306 (Handover OTP: 999812)','Dear Dr. Charith Jayasundara (Updated),\nSenior Lecturer Grade I,\n\nThe examination for ICT1306 (Object Oriented Programming) conducted on 8/15/2026 has concluded. The physical examination paper packets (approx. 75 scripts) have been deposited and secured at the Examinations Branch (AR Office).\n\nPlease proceed to the AR Office to collect your paper packets.\n\n==================================================\nYOUR PHYSICAL SCRIPT COLLECTION OTP:\n>>> 999812 <<<\n==================================================\n\nINSTRUCTIONS FOR HANDOVER:\n1. Visit the Examinations Branch counter in person.\n2. Tell this single-use 6-digit OTP code to the Senior Assistant Registrar (Examinations).\n3. The AR Office will verify the code in the system to confirm physical packet handover.\n4. Upon verification, your 3-calendar-month first marking deadline will officially commence.\n\nExaminations Branch & Department of Computing\nFaculty of Applied Sciences, Rajarata University of Sri Lanka',NULL,'2026-10-17 21:42:08.088'),(58,5,23,'COURIER_DISPATCHED','Scripts Couriered','Scripts have been dispatched to you for second marking (Ref: SPEEDPOST-99921). Please acknowledge receipt once received.',NULL,'2026-10-17 21:42:08.258'),(59,5,23,'COURIER_DISPATCHED_TO_SECOND_EXAMINER','[Scripts Dispatched] Courier Reference for ICT1306 Second Marking','Dear Prof. Jagath K. Gunathilake,\n\nAnswer scripts for ICT1306 (Object Oriented Programming) have been dispatched to you via courier by the AR Office (Examinations Branch).\n\nCourier Tracking Reference: SPEEDPOST-99921\nSecond Marking Due Date: 11/18/2026 (1 Calendar Month)\n\nPlease sign in to acknowledge receipt upon receiving the physical package.\n\nExaminations Branch,\nRajarata University of Sri Lanka',NULL,'2026-10-17 21:42:13.822'),(60,2,23,'SECOND_MARKING_COMPLETE','Second Marking Completed','Second marking report and scripts have been received. You can now download the report and prepare the final marksheet.',NULL,'2026-10-17 21:42:13.911'),(61,2,23,'SECOND_MARKING_COMPLETED_PREPARE_MARKSHEET','Second Marking Completed: Prepare Final Marksheet for ICT1306','Dear Dr. Charith Jayasundara (Updated),\n\nSecond marking for ICT1306 (Object Oriented Programming) is now complete. The Second Marker Report PDF has been uploaded and scripts have been safely returned to the AR Office.\n\nYou can now download the Second Marker Report from the portal, compile your Continuous Assessment (CA) marks, and upload/submit the Final Marksheet for HOD approval.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 21:42:19.245'),(62,1,23,'FINAL_MARKSHEET_SUBMITTED_FOR_HOD_APPROVAL','[HOD Review Required] Final Marksheet Submitted: ICT1306 (Dr. Charith Jayasundara (Updated))','Dear Dr. K. A. S. H. Kulathilake,\nHead of Department,\n\nThe Final Marksheet for ICT1306 (Object Oriented Programming) has been compiled and submitted by the First Examiner (Dr. Charith Jayasundara (Updated)).\n\nAll prerequisite checkpoints (First Report, Scripts Returned, Second Report, AR Received) have been completed.\n\nPlease sign in to the HOD Dashboard to review the marksheet and either grant Final Approval (which permanently locks the workflow) or request revisions.\n\nDepartment of Computing,\nRajarata University of Sri Lanka',NULL,'2026-10-17 21:42:24.671'),(63,2,23,'CHANGES_REQUESTED','Revision Requested for Final Marksheet','HOD has requested revisions: Please recheck CA mark weighting for assignment 2',NULL,'2026-10-17 21:42:24.706'),(64,1,23,'FINAL_MARKSHEET_SUBMITTED_FOR_HOD_APPROVAL','[HOD Review Required] Final Marksheet Submitted: ICT1306 (Dr. Charith Jayasundara (Updated))','Dear Dr. K. A. S. H. Kulathilake,\nHead of Department,\n\nThe Final Marksheet for ICT1306 (Object Oriented Programming) has been compiled and submitted by the First Examiner (Dr. Charith Jayasundara (Updated)).\n\nAll prerequisite checkpoints (First Report, Scripts Returned, Second Report, AR Received) have been completed.\n\nPlease sign in to the HOD Dashboard to review the marksheet and either grant Final Appr