DROP TABLE IF EXISTS `system_audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system_audit_log` (
  `user_id` int(11) DEFAULT NULL,
  `action` varchar(191) NOT NULL,
  `ip_address` varchar(191) DEFAULT NULL,
  `timestamp` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `exam_schedule_id` int(11) DEFAULT NULL,
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `result` varchar(191) NOT NULL,
  `safe_metadata_json` text DEFAULT NULL,
  `user_agent` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `system_audit_log_timestamp_idx` (`timestamp`),
  KEY `system_audit_log_exam_schedule_id_fkey` (`exam_schedule_id`),
  KEY `system_audit_log_user_id_fkey` (`user_id`),
  CONSTRAINT `system_audit_log_exam_schedule_id_fkey` FOREIGN KEY (`exam_schedule_id`) REFERENCES `exam_schedules` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `system_audit_log_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=206 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
