-- workflow history and stage transition audit log

DROP TABLE IF EXISTS `workflow_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `workflow_events` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exam_schedule_id` int(11) NOT NULL,
  `actor_user_id` int(11) NOT NULL,
  `event_type` varchar(191) NOT NULL,
  `from_status` varchar(191) NOT NULL,
  `to_status` varchar(191) NOT NULL,
  `description` text NOT NULL,
  `metadata_json` text DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `workflow_events_exam_schedule_id_fkey` (`exam_schedule_id`),
  KEY `workflow_events_actor_user_id_fkey` (`actor_user_id`),
  CONSTRAINT `workflow_events_actor_user_id_fkey` FOREIGN KEY (`actor_user_id`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `workflow_events_exam_schedule_id_fkey` FOREIGN KEY (`exam_schedule_id`) REFERENCES `exam_schedules` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=303 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

